class CustomSlider : public Slider
{
public:
    CustomSlider()
    {
        setSliderStyle(Slider::LinearHorizontal);
        setTextBoxStyle(Slider::TextBoxBelow, false, 80, 20);
        setRange(0.0, 1.0, 0.01);
        setVelocityBasedMode(true);
    }

    void paint(Graphics& g) override
    {
        auto bounds = getLocalBounds().toFloat();
        auto sliderArea = bounds;

        // Draw track background
        g.setColour(Colours::darkgrey);
        g.fillRoundedRectangle(sliderArea, 4.0f);

        // Draw filled portion
        auto fillWidth = sliderArea.getWidth() * getValue();
        auto fillArea = sliderArea.withWidth(fillWidth);
        g.setColour(findColour(accentColourId));
        g.fillRoundedRectangle(fillArea, 4.0f);

        // Draw thumb
        auto thumbX = sliderArea.getX() + fillWidth;
        auto thumbBounds = Rectangle<float>(thumbX - 8, sliderArea.getY(), 16, sliderArea.getHeight());
        g.setColour(Colours::white);
        g.fillEllipse(thumbBounds);

        Slider::paint(g);
    }
};

class LinearSlider : public Slider
{
public:
    LinearSlider()
    {
        setSliderStyle(Slider::LinearHorizontal);
        setTextBoxStyle(Slider::NoTextBox, false, 0, 0);
    }

    void paint(Graphics& g) override
    {
        auto bounds = getLocalBounds();
        auto trackHeight = 4;
        auto trackBounds = bounds.withHeight(trackHeight).withY((bounds.getHeight() - trackHeight) / 2);

        // Track background
        g.setColour(Colours::grey.withAlpha(0.3f));
        g.fillRoundedRectangle(trackBounds.toFloat(), 2.0f);

        // Filled track
        auto fillAmount = (float)proportionOfLength(getValue());
        auto fillBounds = trackBounds.withWidth((int)(trackBounds.getWidth() * fillAmount));
        g.setColour(findColour(Slider::trackColourId));
        g.fillRoundedRectangle(fillBounds.toFloat(), 2.0f);

        // Thumb
        auto thumbX = trackBounds.getX() + trackBounds.getWidth() * fillAmount;
        auto thumbRadius = 10.0f;
        auto thumbCentre = Point<float>(thumbX, trackBounds.getCentreY());

        g.setColour(findColour(Slider::thumbColourId));
        g.fillEllipse(thumbCentre, thumbRadius);

        if (isMouseOver())
        {
            g.setColour(Colours::white.withAlpha(0.2f));
            g.drawEllipse(thumbCentre, thumbRadius + 2.0f, 1.5f);
        }
    }

    void mouseDown(const MouseEvent& e) override
    {
        dragStartValue = getValue();
        Slider::mouseDown(e);
    }

    void mouseDrag(const MouseEvent& e) override
    {
        auto mousePos = e.getPosition().toFloat();
        auto bounds = getLocalBounds().toFloat();

        // Convert mouse position to slider value
        auto proportion = (mousePos.x - bounds.getX()) / bounds.getWidth();
        proportion = jlimit(0.0f, 1.0f, proportion);

        setValue(proportion, sendNotification);
    }

private:
    double dragStartValue = 0.0;
};

class VolumeFader : public Slider
{
public:
    VolumeFader()
    {
        setSliderStyle(Slider::LinearVertical);
        setTextBoxStyle(Slider::TextBoxBelow, false, 60, 18);
        setRange(-60.0, 12.0, 0.1);
        setSkewFactorFromMidPoint(0.0);  // Linear dB response
    }

    void paint(Graphics& g) override
    {
        auto bounds = getLocalBounds();
        auto trackWidth = 20;
        auto trackBounds = bounds.withWidth(trackWidth).withX((bounds.getWidth() - trackWidth) / 2);

        // Track background
        g.setColour(Colours::darkgrey);
        g.fillRoundedRectangle(trackBounds.reduced(2).toFloat(), 3.0f);

        // Filled portion (from bottom)
        auto normalisedValue = (getValue() - getMinimum()) / (getMaximum() - getMinimum());
        auto fillHeight = trackBounds.getHeight() * normalisedValue;
        auto fillBounds = trackBounds.withY(trackBounds.getBottom() - fillHeight).withHeight(fillHeight);

        // Gradient fill
        auto gradient = ColourGradient(Colours::green.darker(),
                                        trackBounds.getBottomLeft().toFloat(),
                                        Colours::green.brighter(),
                                        trackBounds.toFloat().getTopLeft(),
                                        false);
        g.setGradientFill(gradient);
        g.fillRoundedRectangle(fillBounds.reduced(2).toFloat(), 3.0f);

        // Draw dB markers
        g.setColour(Colours::grey);
        g.setFont(10.0f);
        for (float db = -60.0f; db <= 12.0f; db += 12.0f)
        {
            auto y = trackBounds.getBottom() - (db + 60.0f) / 72.0f * trackBounds.getHeight();
            g.drawHorizontalLine((int)y, trackBounds.getRight() + 5, trackBounds.getRight() + 10);
        }
    }
};

class SliderWithValueDisplay : public Slider
{
public:
    SliderWithValueDisplay()
    {
        setTextBoxStyle(Slider::NoTextBox, false, 0, 0);
    }

    String getTextFromValue(double value) override
    {
        if (parameter != nullptr)
        {
            return parameter->getText(value, 4);
        }

        // Default formatting
        if (value >= 1000.0)
            return String(value / 1000.0, 1) + " kHz";
        if (value >= 1.0)
            return String(value, 1) + " Hz";

        return String(value, 2);
    }

    void paint(Graphics& g) override
    {
        // Draw slider track and thumb...

        // Draw value text
        g.setColour(findColour(Slider::textColourId));
        g.setFont(12.0f);
        g.drawText(getTextFromValue(getValue()), 
                   getLocalBounds().removeFromBottom(20),
                   Justification::centred);
    }

private:
    AudioProcessorParameter* parameter = nullptr;
};

// In your AudioProcessorEditor
std::unique_ptr<Slider> slider;
std::unique_ptr<AudioProcessorValueTreeState::SliderAttachment> attachment;

void setupSlider(AudioProcessorValueTreeState& apvts, const String& paramID)
{
    slider = std::make_unique<CustomSlider>();
    addAndMakeVisible(slider.get());

    attachment = std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(
        apvts, paramID, *slider);
}

